module guess_circle (\n    input wire [7:0] n,\n    input wire [7:0] values [0:15],\n    output reg [7:0] result [0:15],\n    output reg [3:0] count\n);\n    integer i, j, k, l, m, p, q;\n    reg [7:0] unique_val[0:15];\n    reg [15:0] unique_pos[0:15];\n    reg [15:0] cw_int[0:15];\n    reg [15:0] ccw_int[0:15];\n    reg [0:15] is_good;\n    reg [7:0] good_vals[0:15];\n    integer unique_count;\n    integer good_count;\n    integer half_n;\n    integer found;\n    integer cond_met;\n    reg [15:0] inter1;\n    reg [15:0] inter2;\n    reg in_inter1;\n    reg in_inter2;\n    integer valid_cw;\n    integer valid_ccw;\n    integer dist_cw;\n    integer dist_ccw;\n    reg [7:0] temp;\n\n    always @(*) begin\n        // Initialization\n        unique_count = 0;\n        good_count = 0;\n        for (i=0; i<16; i=i+1) begin\n            unique_val[i] = 8'd0;\n            unique_pos[i] = 16'd0;\n            cw_int[i] = 16'd0;\n            ccw_int[i] = 16'd0;\n            is_good[i] = 1'b0;\n            good_vals[i] = 8'd0;\n        end\n        half_n = (n >> 1);\n\n        // Extract unique values and positions\n        for (i=0; i < n; i=i+1) begin\n            found = 1'b0;\n            for (j=0; j < unique_count; j=j+1) begin\n                if (values[i] == unique_val[j]) begin\n                    unique_pos[j][i] = 1'b1;\n                    found = 1'b1;\n                    j = unique_count;\n                end\n            end\n            if (!found) begin\n                unique_val[unique_count] = values[i];\n                unique_pos[unique_count][i] = 1'b1;\n                unique_count = unique_count + 1;\n            end\n        end\n\n        // Compute cw_int and ccw_int for each unique value\n        for (k=0; k < unique_count; k=k+1) begin\n            for (p=0; p < n; p=p+1) begin\n                valid_cw = 1;\n                valid_ccw = 1;\n                for (q=0; q < n; q=q+1) begin\n                    if (unique_pos[k][q]) begin\n                        dist_cw = (p >= q) ? (p - q) : (p + n - q);\n                        dist_ccw = (q >= p) ? (q - p) : (q + n - p);\n                        if (dist_cw >= half_n) valid_cw = 0;\n                        if (dist_ccw >= half_n) valid_ccw = 0;\n                    end\n                end\n                cw_int[k][p] = valid_cw;\n                ccw_int[k][p] = valid_ccw;\n            end\n        end\n\n        // Compute goodness for each unique val\n        for (k=0; k < unique_count; k=k+1) begin\n            is_good[k] = 1'b1;\n            for (l=0; l < unique_count; l=l+1) begin\n                if (l != k) begin\n                    cond_met = 0;\n                    for (m=0; m < unique_count; m=m+1) begin\n                        if (m != k && m != l) begin\n                            inter1 = cw_int[k] & ccw_int[l];\n                            inter2 = ccw_int[k] & cw_int[l];\n                            in_inter1 = ((unique_pos[m] & ~inter1) == 16'd0);\n                            in_inter2 = ((unique_pos[m] & ~inter2) == 16'd0);\n                            if (in_inter1 || in_inter2) begin\n                                cond_met = 1;\n                                m = unique_count;\n                            end\n                        end\n                    end\n                    if (!cond_met) begin\n                        is_good[k] = 1'b0;\n                        l = unique_count;\n                    end\n                end\n            end\n        end\n\n        // Collect good values\n        good_count = 0;\n        for (k=0; k < unique_count; k=k+1) begin\n            if (is_good[k]) begin\n                good_vals[good_count] = unique_val[k];\n                good_count = good_count + 1;\n            end\n        end\n\n        // Bubble sort good_vals\n        for (i=0; i < good_count; i=i+1) begin\n            for (j=0; j < good_count - i - 1; j=j+1) begin\n                if (good_vals[j] > good_vals[j+1]) begin\n                    temp = good_vals[j];\n                    good_vals[j] = good_vals[j+1];\n                    good_vals[j+1] = temp;\n                end\n            end\n        end\n\n        // Assign outputs\n        count = good_count;\n        for (i=0; i < 16; i=i+1) begin\n            result[i] = (i < good_count) ? good_vals[i] : 8'd0;\n        end\n    end\n\nendmodule